	//criação de camada base osm
	var osm = L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', {
	maxZoom: 20,
    attribution: '© OpenStreetMap | ' + 'Desenvolvido por APC Edgar Dias'
	});
	//criação da camada de bairros
	var bairros = L.geoJSON(bairrosDP,{style: myStyle})
	
	.bindPopup(function (layer){
		return layer.feature.properties.nome + '<br>Circunscrição: ' + layer.feature.properties.Delegacia;
	});
	
	
	//criação do mapa com coordenadas como centro, zoom e camadas <layers:osm, Delegacias>
	var map = L.map('map', {
    center: [1.6245487781245278, -51.63269374105803],
    zoom: 7,
	
	layers: [osm, bairros]
	
	});
	
	var dpGeral = new L.LayerGroup();
		
	map.addLayer(dpGeral);
		
	map.addControl( new L.Control.Search({layer:dpGeral}));
		
	for(i in delegacias) {
		let titulo = delegacias[i].titulo,
		endereco = delegacias[i].endereco,
		titular = delegacias[i].titular,
		adjunto = delegacias[i].adjunto,
		bairro = delegacias[i].bairros,
		email = delegacias[i].email,
		loc = delegacias[i].coords,//posição do layer
		rota = delegacias[i].rota;
		// adjunto.length == 0 ? adjunto = "" : adjunto = delegacias[i].adjunto;
		// titular.length == 0 ? titular = "Não informado" : titular
		nomeBairro = "";
		for (let i of bairro){
		nomeBairro = i
		marker = new L.Marker(new L.latLng(loc), {titulo:nomeBairro, title: titulo}),//Após o title, insere-se o alvo da busca, no caso os nomes dos bairros
		marker.bindPopup(`<h5><center>${titulo}<center></h5><p style="font-size:10px;"><br><b>Delegado Titular</b>: ${titular}<br><b>Delegado Adjunto</b>: ${adjunto}<br><b>E-mail: </b>${email}<br><b>Endereço:</b> ${endereco}</p><br><a href=${rota} target="_blanck" title="Clicar para definir rota "><span>Rota</span></a>`);
						
		dpGeral.addLayer(marker);
						
		}
		}
		//layer com visibilidade sob controle do usuário
	var baseMaps = {
    	"OpenStreetMap": osm
	};

	//layer com visibilidade sob controle do usuário
	var overlayMaps = {
   	"Bairros": bairros,
	};

		
	// adiciona o controle de layers acima definidos
	var layerControl = L.control.layers(baseMaps, overlayMaps).addTo(map);
	
	//insere escala ao final
	L.control.scale().addTo(map);
		

	
	
	
